#!/bin/bash
# Referee round 2 for L008 (f(16) = 10).  Reproduces every computation of the review
# results/reviews/L008-f16-equals-10__referee__<UTC>.md.  Run from this directory; total CPU about 45 min (nice 5).
# nauty: only the library routine densenauty is used (canonical labelling), compiled from the nauty 2.8.8 sources
# (PyPI sdist pynauty-2.8.8.1) copied into nauty_lib/; headers generated by sed (see nauty_lib/README in the review).
set -e
# Key small outputs of the review run are copied to evidence/ (out/ is git-ignored).
R=$(pwd); P=/home/user/Erdos-757/experiments/prover/L008; F=/home/user/Erdos-757/experiments/20261017-0300-n16-via-i11
CF="-O3 -march=native -DWORDSIZE=64 -DMAXN=WORDSIZE -Inauty_lib"
# --- nauty library (canonical labelling only)
(cd nauty_lib && for f in nauty nautil naugraph schreier naurng nautinv; do gcc -O3 -march=native -c -DWORDSIZE=64 -DMAXN=WORDSIZE $f.c -o $f.o; done && ar rcs libnauty_r2.a nauty.o nautil.o naugraph.o schreier.o naurng.o nautinv.o)
# --- own programs
gcc $CF -o bin/bfs_enum src/bfs_enum.c nauty_lib/libnauty_r2.a
gcc $CF -o bin/canon_list src/canon_list.c nauty_lib/libnauty_r2.a
gcc -O3 -march=native -o bin/ext_r2 src/ext_r2.c
gcc -O3 -march=native -o bin/bf_lab src/bf_lab.c
gcc -O3 -march=native -o bin/i11_sets src/i11_sets.c
gcc -O3 -march=native -o bin/ext16 src/ext16.c
# --- 1. validation of bfs_enum against labelled brute force (n <= 9, D in {3, inf}, both modes, every m and tau threshold)
for n in 3 4 5 6 7 8; do for D in 3 100; do ./bin/bf_lab $n $D; done; done > out/bf_lab_n3_8.txt
./bin/bf_lab 9 3 > out/bf_lab_n9_D3.txt; ./bin/bf_lab 9 100 > out/bf_lab_n9_Dinf.txt
python3 src/compare_bf.py out/bf_lab_n3_8.txt out/bf_lab_n9_D3.txt out/bf_lab_n9_Dinf.txt       # 390 cells, 0 mismatches
python3 src/bf_vs_proof_enums.py out/bf_lab_n3_8.txt out/bf_lab_n9_D3.txt out/bf_lab_n9_Dinf.txt   # enum_conn and conn_dfs3 (rerun/bin) vs brute force: 328, 0 mismatches
# --- 2. the proof's enumerations C2, C3 by generate-and-deduplicate, and comparison with the prover's/falsifier's lists
./bin/bfs_enum 12 10 5 3 1 1 > out/bfs_12_10_5_d3.txt                 # 197 classes
./bin/bfs_enum 15 11 6 3 1 1 > out/bfs_15_11_6_d3.txt                 # 49 classes
./bin/bfs_enum 15 11 6 3 0 1 > out/bfs_15_11_6_d3_ALL.txt             # 261 classes (any connectivity, isolated vertices allowed)
./bin/canon_list FOUND 12 < out/bfs_12_10_5_d3.txt | awk '{print $1}' | sort > out/keys_bfs_12.txt
zcat $P/indep/mine_12_10_5_deg3.txt.gz | ./bin/canon_list FOUND 12 | awk '{print $1}' | sort -u > out/keys_enumconn_12.txt
zcat $F/R12_labelled.txt.gz | ./bin/canon_list FOUND 12 | awk '{print $1}' | sort -u > out/keys_falsifier_12.txt
cmp out/keys_bfs_12.txt out/keys_enumconn_12.txt; cmp out/keys_bfs_12.txt out/keys_falsifier_12.txt
./bin/canon_list FOUND 15 < out/bfs_15_11_6_d3.txt | awk '{print $1}' | sort > out/keys_bfs_15.txt
zcat $P/indep/mine_15_11_6_deg3.txt.gz | ./bin/canon_list FOUND 15 | awk '{print $1}' | sort -u > out/keys_enumconn_15.txt
(zcat $F/g15_11_6_part0.txt.gz; zcat $F/g15_11_6_part1.txt.gz) | ./bin/canon_list FOUND 15 | awk '{print $1}' | sort -u > out/keys_falsifier_15.txt
cmp out/keys_bfs_15.txt out/keys_enumconn_15.txt; cmp out/keys_bfs_15.txt out/keys_falsifier_15.txt
# --- 3. extension + definitional filters on the class representatives (case A, case B, and all 261 = route without Step 4)
sed -n 's/^\(FOUND:.*\) AUT=.*$/\1 (12,13,14)/p' out/bfs_12_10_5_d3.txt > out/inputA_classes.txt
sed -n 's/^\(FOUND:.*\) AUT=.*$/\1/p' out/bfs_15_11_6_d3.txt > out/inputB_classes.txt
sed -n 's/^\(FOUND:.*\) AUT=.*$/\1/p' out/bfs_15_11_6_d3_ALL.txt > out/inputALL_classes.txt
for c in A B ALL; do ./bin/ext_r2 EXT 15 7 3 < out/input${c}_classes.txt > out/ext_${c}.txt; tail -1 out/ext_${c}.txt; done
bash src/cmp_enumconn.sh > out/cmp_enumconn.log 2>&1   # enum_conn vs bfs_enum class sets, n = 10..12 (stopped by a 590 s timeout in the review run)
python3 src/examples.py
# --- 4. validation of delete-a-degree-3-vertex-and-extend against direct enumeration (5 small analogues)
bash src/ext_validate.sh
# --- 5. Lemma A' re-checked with and without Henning-Yeo (all cells n <= 15 with lo <= m; (15,13,>=7) times out at 900 s)
bash src/hyfree_driver.sh > out/hyfree_summary.log 2>&1
python3 src/cells.py 16
# --- 6. controls for the F7 / P3 / tau detectors (mine and the prover's)
python3 src/make_controls.py; ./bin/ext_r2 FILTER 0 v < controls/controls.txt; $P/indep/filter_hits FOUND < controls/controls.txt | tail -1
# --- 7. re-runs of the proof's own programs: commands in rerun/README.txt (run from rerun/)
# --- 8. realizable data: every induced subset of the record sets, Fibonacci, gluings, census classes, 15- and 16-point sets
python3 src/make_basic_sets.py
./bin/i11_sets < data_tests/basic_sets.txt; ./bin/i11_sets < data_tests/census14.txt > data_tests/census14_results.txt
./bin/i11_sets < data_tests/census12.txt > data_tests/census12_results.txt; ./bin/i11_sets < data_tests/ext15.txt > data_tests/ext15_results.txt
./bin/ext16 < data_tests/ext15.txt > data_tests/ext16_sets.txt; ./bin/i11_sets < data_tests/ext16_sets.txt > data_tests/ext16_results.txt
# --- 9. the witness C16
(cd witness && python3 check_c16.py) && (cd /home/user/Erdos-757 && python3 judge/judge.py $R/witness/L008r2-C16.json)
